import * as d3 from 'd3';
import { ComponentDef } from '../../components/types';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  drawStepBox,
  drawTensor,
  drawTensorGrid,
  fmtNum,
  Sel
} from '../primitives';
import { renderGenericDetailed } from './generic';
import { StepInfo } from './index';

export function renderAttentionDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const variant = String(params.variant || 'standard');
  if (variant !== 'standard') {
    const variantMeta: ComponentDef = {
      ..._meta,
      name: variant === 'mla' ? 'MLA (Latent Attention)' : 'Linear Attention',
      description:
        variant === 'mla'
          ? 'Multi-head Latent Attention compresses keys and values into a shared latent vector, reducing KV cache size.'
          : 'Linear attention applies feature maps to queries and keys so attention complexity grows linearly with sequence length.'
    };
    return renderGenericDetailed(g, params, variantMeta, _graph);
  }

  const dModel = (params.d_model as number) || 512;
  const nHeads = (params.n_heads as number) || 8;
  const seqLen = (params.seq_len as number) || 128;
  const dHead = Math.floor(dModel / nHeads);
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  const dModelSel = g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>;

  // Header
  drawLabel(g, cx, y, 'Multi-Head Attention', { size: 16, weight: '700' });
  y += 22;
  drawLabel(g, cx, y, `d_model=${dModel}  n_heads=${nHeads}  seq_len=${seqLen}  d_head=${dHead}`, {
    size: 10,
    color: '#888'
  });
  y += 40;

  // Input tensor
  drawTensor(g, cx - 110, y, 220, 30, `x: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  // Step 1: Q/K/V projections
  const grp1 = dModelSel.append('g').attr('class', 'step-node step-attn-1').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp1 as unknown as Sel, cx - 120, 0, 240, 46, 'Project to Q, K, V', {
    step: 1, fill: '#e8f5e9', stroke: '#4caf50',
    formula: 'Q = xWq, K = xWk, V = xWv'
  });
  y += 60;

  const matrixY = y;
  const matGrp1 = dModelSel.append('g').attr('class', 'step-node step-attn-1');
  drawMatrixBlock(matGrp1 as unknown as Sel, cx - 140, matrixY, {
    width: 70, height: 50, label: 'Wq', sublabel: `[${dModel}, ${dModel}]`,
    fill: '#e3f2fd', stroke: '#1976d2', dimRight: `d_head=${dHead}`
  });
  drawMatrixBlock(matGrp1 as unknown as Sel, cx - 35, matrixY, {
    width: 70, height: 50, label: 'Wk', sublabel: `[${dModel}, ${dModel}]`,
    fill: '#e3f2fd', stroke: '#1976d2'
  });
  drawMatrixBlock(matGrp1 as unknown as Sel, cx + 70, matrixY, {
    width: 70, height: 50, label: 'Wv', sublabel: `[${dModel}, ${dModel}]`,
    fill: '#e3f2fd', stroke: '#1976d2'
  });
  y += 70;

  drawArrow(g, cx, y - 70, cx, y - 20, { color: '#78909c' });

  // Step 2: Split heads
  const grp2 = dModelSel.append('g').attr('class', 'step-node step-attn-2').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp2 as unknown as Sel, cx - 120, 0, 240, 46, 'Split into n_heads', {
    step: 2, fill: '#e3f2fd', stroke: '#1976d2',
    formula: `[b, n_heads, seq, d_head]`
  });
  y += 60;

  const headGrp = dModelSel.append('g').attr('class', 'step-node step-attn-2');
  drawTensorGrid(headGrp as unknown as Sel, cx - 80, y, {
    rows: 4, cols: nHeads, cellW: 14, cellH: 14,
    maxDisplayRows: 4, maxDisplayCols: 8,
    label: `heads × seq × d_head`, showEllipsis: true
  });
  y += 90;

  // Step 3: Scaled dot-product attention
  const grp3 = dModelSel.append('g').attr('class', 'step-node step-attn-3').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp3 as unknown as Sel, cx - 140, 0, 280, 46, 'Scaled Dot-Product Attention', {
    step: 3, fill: '#f3e5f5', stroke: '#7b1fa2',
    formula: 'softmax((QK^T) / sqrt(d_head)) · V'
  });
  y += 60;

  // Attention heatmap
  const heatGrp = dModelSel.append('g').attr('class', 'step-node step-attn-3');
  const cellSize = 10;
  const gridSize = 8;
  const heatmapX = cx - (gridSize * cellSize) / 2;
  for (let r = 0; r < gridSize; r++) {
    for (let c = 0; c < gridSize; c++) {
      const isMasked = c > r;
      heatGrp.append('rect')
        .attr('x', heatmapX + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', isMasked ? '#f5f5f5' : d3.interpolateOranges(0.1 + Math.random() * 0.4))
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }
  drawLabel(heatGrp as unknown as Sel, cx, y + gridSize * cellSize + 14, 'Attention scores (causal mask)', {
    size: 10, color: '#666'
  });
  y += gridSize * cellSize + 36;

  // Step 4: Output projection
  const grp4 = dModelSel.append('g').attr('class', 'step-node step-attn-4').attr('transform', `translate(0, ${y})`);
  drawStepBox(grp4 as unknown as Sel, cx - 120, 0, 240, 46, 'Concatenate heads and project', {
    step: 4, fill: '#fff3e0', stroke: '#f57c00',
    formula: 'out = Concat(head_1, ..., head_h) · Wo'
  });
  y += 60;

  const outMatGrp = dModelSel.append('g').attr('class', 'step-node step-attn-4');
  drawMatrixBlock(outMatGrp as unknown as Sel, cx - 50, y, {
    width: 100, height: 50, label: 'Wo', sublabel: `[${dModel}, ${dModel}]`,
    fill: '#e3f2fd', stroke: '#1976d2'
  });
  y += 70;

  // Output tensor
  drawTensor(g, cx - 110, y, 220, 30, `out: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  // Parameter count
  const qkvParams = dModel * dModel * 3;
  const outParams = dModel * dModel;
  const totalParams = qkvParams + outParams;
  drawLabel(g, cx, y, `Total params: ${fmtNum(totalParams)}  (3×${fmtNum(dModel * dModel)} QKV + ${fmtNum(outParams)} output)`, {
    size: 11, color: '#1976d2', weight: '600'
  });
  y += 28;

  // Explanations
  y = drawExplanation(g, 80, y, totalW - 160,
    'Multi-head attention lets the model attend to information from different representation subspaces at different positions. '
    + 'Each head learns a different type of relationship: syntax, coreference, long-distance dependencies, etc.',
    'insight'
  );
  y += 6;

  y = drawExplanation(g, 80, y, totalW - 160,
    `Computational cost is O(b · n_heads · s² · d_head) = O(b · s² · d_model) FLOPs for the attention matrix, `
    + `and O(4 · b · s · d_model²) for the linear projections. The s² term is why long-context attention is expensive.`,
    'perf'
  );
  y += 6;

  // Cross-link
  drawComponentLink(g, cx - 70, y, 140, 24, 'transformer-block', 'View Transformer Block ↗', {
    fill: '#e3f2fd', stroke: '#1976d2'
  });
  y += 40;

  // Code annotation
  y = drawCodeAnnotation(g, 80, y, totalW - 160,
    'Multi-Head Attention — Attention Is All You Need (Vaswani et al. 2017)',
    [
      'Project input to query, key, and value vectors, split into h heads.',
      `Scale the dot-product by 1/√d_head to keep softmax gradients stable.`,
      `Params: ${fmtNum(totalParams)}. FLOPs per token: ≈${fmtNum(4 * dModel * dModel)} for projections + O(s·d_model) for attention.`
    ],
    [
      `self.Wq = nn.Linear(${dModel}, ${dModel}, bias=False)`,
      `self.Wk = nn.Linear(${dModel}, ${dModel}, bias=False)`,
      `self.Wv = nn.Linear(${dModel}, ${dModel}, bias=False)`,
      `self.Wo = nn.Linear(${dModel}, ${dModel}, bias=False)`,
      '',
      `def forward(self, x):  # x: [batch, seq, ${dModel}]`,
      `    q = self.Wq(x).view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`,
      `    k = self.Wk(x).view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`,
      `    v = self.Wv(x).view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`,
      `    scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})`,
      `    attn = F.softmax(scores.masked_fill(mask == 0, float('-inf')), dim=-1)`,
      `    return self.Wo((attn @ v).transpose(1, 2).reshape(b, s, ${dModel}))`
    ]
  );

  const steps: StepInfo[] = [
    {
      id: 1, label: 'Project to Q, K, V', shortLabel: 'Q/K/V Projection',
      formula: 'Q = xWq, K = xWk, V = xWv',
      explanation: `Three linear projections transform the input into query, key, and value matrices. Each has ${fmtNum(dModel * dModel)} parameters. The queries and keys are used to compute attention scores; values carry the information to be aggregated.`,
      code: { title: 'Q/K/V Projection', lines: [
        `self.Wq = nn.Linear(${dModel}, ${dModel}, bias=False)`,
        `self.Wk = nn.Linear(${dModel}, ${dModel}, bias=False)`,
        `self.Wv = nn.Linear(${dModel}, ${dModel}, bias=False)`,
        '',
        `q = x @ Wq  # [batch, seq, ${dModel}]`,
        `k = x @ Wk  # [batch, seq, ${dModel}]`,
        `v = x @ Wv  # [batch, seq, ${dModel}]`,
      ] },
      svgGroup: 'step-attn-1', color: '#4caf50', fill: '#e8f5e9',
    },
    {
      id: 2, label: 'Split into n_heads', shortLabel: 'Head Split',
      formula: `[b, n_heads, seq, d_head]`,
      explanation: `The d_model dimension is reshaped into ${nHeads} heads of dimension ${dHead}. Each head operates independently, allowing the model to learn different attention patterns in parallel.`,
      code: { title: 'Multi-Head Reshape', lines: [
        `# Reshape: [batch, seq, ${dModel}] → [batch, ${nHeads}, seq, ${dHead}]`,
        `q = q.view(batch, seq, ${nHeads}, ${dHead}).transpose(1, 2)`,
        `k = k.view(batch, seq, ${nHeads}, ${dHead}).transpose(1, 2)`,
        `v = v.view(batch, seq, ${nHeads}, ${dHead}).transpose(1, 2)`,
      ] },
      svgGroup: 'step-attn-2', color: '#1976d2', fill: '#e3f2fd',
    },
    {
      id: 3, label: 'Scaled Dot-Product Attention', shortLabel: 'Attention',
      formula: 'softmax((QK^T) / √d_head) · V',
      explanation: `Each position computes a weighted sum over all other positions. The scale factor 1/√${dHead} prevents dot products from growing too large, which would push softmax into regions with tiny gradients. Causal masking prevents attending to future positions.`,
      code: { title: 'Scaled Dot-Product', lines: [
        `scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})`,
        `# Apply causal mask: set future positions to -inf`,
        `scores = scores.masked_fill(mask == 0, float('-inf'))`,
        `attn = F.softmax(scores, dim=-1)  # [batch, ${nHeads}, seq, seq]`,
        `output = attn @ v  # [batch, ${nHeads}, seq, ${dHead}]`,
      ] },
      svgGroup: 'step-attn-3', color: '#7b1fa2', fill: '#f3e5f5',
    },
    {
      id: 4, label: 'Concatenate heads and project', shortLabel: 'Output Projection',
      formula: 'out = Concat(heads) · Wo',
      explanation: `The ${nHeads} head outputs are concatenated back to d_model dimension and projected through Wo. This allows the model to combine information from all attention heads into a single representation.`,
      code: { title: 'Output Projection', lines: [
        `# Concatenate: [batch, ${nHeads}, seq, ${dHead}] → [batch, seq, ${dModel}]`,
        `out = output.transpose(1, 2).reshape(batch, seq, ${dModel})`,
        `return self.Wo(out)  # [batch, seq, ${dModel}]`,
        `# Wo params: ${fmtNum(dModel * dModel)}`,
      ] },
      svgGroup: 'step-attn-4', color: '#f57c00', fill: '#fff3e0',
    },
  ];

  return { width: totalW, height: y + 20, steps };
}
